// What every engine's standby copy shares (spec #176): the row an engine fills in, and the two files a copy
// keeps beside its data. https://deplo.build/docs/operations/clusters/standby-copy

export interface StandbyArgs {
  /** The database's own name on its network; the copy reaches it there. */
  host: string;
  username: string;
  dbName: string;
  port: number;
  /** The copy's own login password: generated by Deplo, sent inside the agent's RPC, never shown. */
  password: string;
}

export interface StandbyEngine {
  /** What the engine is called in a sentence. */
  label: string;
  /** The oldest version that can keep a copy, as far down as it matters: "13", "11.4", "8.0.26". */
  minVersion: string;
  /** How many servers the cluster needs before this engine keeps a copy; two when unset. */
  minMembers?: number;
  /** What the database's own start command gains while it keeps a copy. A change restarts the database once. */
  settings?: string[];
  /** Run in the database's container: lets a copy follow it. Safe to run again. */
  prepare(a: StandbyArgs): string;
  /** Run in the database's container once no copy follows it. */
  retire(a: StandbyArgs): string;
  /** The copy's start command and what it adds to the environment; `seed` marks the data this copy made. */
  start(a: StandbyArgs & { primaryHost: string; seed: string }): {
    command: string[];
    env: string[];
  };
  /** Run in the copy's container: prints `following`, `waiting`, `seeding` or `behind`. */
  check: string;
  /** Run in the copy's container on a failover; it fails when the copy had stopped following. */
  promote: { user: string; command: string[] };
  /** What the database's own server keeps for the copy, as the switch states it; empty when nothing more. */
  kept: string;
}

/** How long a copy may go without following before it is no better than a backup: the failover backup's own window. */
export const STALE_MINUTES = 15;

/** The copy's login on the database: it may read and follow, never write. */
export const LOGIN = "deplo_standby";

export const sh = (v: string) => `'${v.replace(/'/g, `'\\''`)}'`;

/** The copy's service and container: `_` is in no database's name, so it never answers to one. */
export const standbyContainer = (host: string) => `${host}_standby`;

/** The two files a copy keeps in its data folder: the seed its data came from, and when it last followed. */
export function marks(dir: string) {
  const seeded = `"${dir}/deplo-standby-seed"`;
  const following = `"${dir}/deplo-standby-following"`;
  const within = (minutes: number) =>
    `[ -n "$(find ${following} -mmin -${minutes} 2>/dev/null)" ]`;
  const unseeded = `[ "$(cat ${seeded} 2>/dev/null)" != "$DEPLO_STANDBY_SEED" ]`;
  const followed = within(STALE_MINUTES);
  return {
    seeded,
    following,
    /** True while the data here did not come from the seed asked for. */
    unseeded,
    /** True while the copy followed its database within the last STALE_MINUTES. */
    followed,
    /** Marks the data as this seed's and as following: run once the copy has all of its database. */
    arrive: `printf %s "$DEPLO_STANDBY_SEED" > ${seeded}; touch ${following}`,
    check: `if ${unseeded}; then echo seeding; elif ${within(1)}; then echo following; elif ${followed}; then echo waiting; else echo behind; fi`,
    /** Opens every promotion: a copy that stopped following is never promoted, so the backup is restored instead. */
    refuse: `${followed} || { echo "the standby copy had not followed its database for ${STALE_MINUTES} minutes" >&2; exit 1; }`,
  };
}
